import { Controller, Get, Post, Put, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const USE_VALUES = ['사용', '미사용'];
const IPV4 = /^(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)(\.(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)){3}$/;

function isIpv6(v: string): boolean {
  if (!/^[0-9a-fA-F:]+$/.test(v) || v.includes(':::')) {
    return false;
  }
  const parts = v.split('::');
  if (parts.length > 2) {
    return false;
  }
  const groups = v.split(':').filter((g) => g !== '');
  if (groups.some((g) => g.length > 4)) {
    return false;
  }
  if (parts.length === 2) {
    return groups.length <= 7;
  }
  return groups.length === 8 && !v.startsWith(':') && !v.endsWith(':');
}

function parseBody(data: Record<string, unknown>) {
  const ipAddress = typeof data['ipAddress'] === 'string' ? data['ipAddress'].trim() : '';
  if (!ipAddress) {
    throw new ApiError(400, 'VALIDATION_FAILED', '허용 IP를 입력해 주세요.');
  }
  const rawDesc = data['description'];
  if (rawDesc !== undefined && rawDesc !== null && typeof rawDesc !== 'string') {
    throw new ApiError(400, 'VALIDATION_FAILED', '설명 형식이 올바르지 않습니다.');
  }
  const description = typeof rawDesc === 'string' && rawDesc.trim() !== '' ? rawDesc.trim() : null;
  if (description !== null && description.length > 500) {
    throw new ApiError(400, 'VALIDATION_FAILED', '설명은 500자 이하로 입력해 주세요.');
  }
  const useYn = data['useYn'];
  if (typeof useYn !== 'string' || !USE_VALUES.includes(useYn)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '사용 여부는 사용 또는 미사용이어야 합니다.');
  }
  if (ipAddress.length > 45 || !(IPV4.test(ipAddress) || isIpv6(ipAddress))) {
    throw new ApiError(422, 'INVALID_IP_FORMAT', 'IP 형식이 올바르지 않습니다.');
  }
  return { ipAddress, description, useYn };
}

@Controller('api/v1')
export class FnSfr01705Controller {
  @Get('/allowed-ips')
  async listAllowedIps(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const query = checks.queryOf(req.query);
    const pageNo = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
    const sizeNo = query['size'] === undefined || query['size'] === '' ? DEFAULT_SIZE : Number(query['size']);
    if (!Number.isInteger(pageNo) || pageNo < 0 || !Number.isInteger(sizeNo) || sizeNo < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 크기가 올바르지 않습니다.');
    }
    const size = Math.min(sizeNo, MAX_SIZE);
    return transaction(async (db) => {
      const items = await db.query(
        'SELECT allowed_ip_id AS "allowedIpId", ip_address AS "ipAddress", description AS "description", use_yn AS "useYn" FROM allowed_ip ORDER BY allowed_ip_id LIMIT :size OFFSET :offset',
        { size, offset: pageNo * size },
      );
      const counts = await db.query('SELECT COUNT(*) AS "total" FROM allowed_ip', {});
      return { items, page: pageNo, size, total: Number(counts[0]['total']) };
    });
  }

  @Post('/allowed-ips')
  @HttpCode(200)
  async createAllowedIp(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const data = checks.inputOf(req.body);
    const v = parseBody(data);
    return transaction(async (db) => {
      const dup = await db.query('SELECT allowed_ip_id FROM allowed_ip WHERE ip_address = :ip', { ip: v.ipAddress });
      if (dup.length > 0) {
        throw new ApiError(409, 'ALLOWED_IP_DUPLICATED', '이미 등록된 IP입니다.');
      }
      const rows = await db.query(
        'INSERT INTO allowed_ip (ip_address, description, use_yn, created_at, updated_at) VALUES (:ip, :description, :useYn, now(), now()) RETURNING allowed_ip_id AS "allowedIpId"',
        { ip: v.ipAddress, description: v.description, useYn: v.useYn },
      );
      // 가정: 변경 이력은 공통 모듈(공통 P15)이 맡는다.
      return { allowedIpId: Number(rows[0]['allowedIpId']) };
    });
  }

  @Put('/allowed-ips/:allowedIpId')
  async updateAllowedIp(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const idText = req.params['allowedIpId'];
    const data = checks.inputOf(req.body);
    if (!/^\d+$/.test(idText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '허용 IP ID가 올바르지 않습니다.');
    }
    const v = parseBody(data);
    return transaction(async (db) => {
      const found = await db.query('SELECT allowed_ip_id FROM allowed_ip WHERE allowed_ip_id = CAST(:id AS bigint)', { id: idText });
      if (found.length === 0) {
        throw new ApiError(404, 'ALLOWED_IP_NOT_FOUND', '허용 IP를 찾을 수 없습니다.');
      }
      const dup = await db.query(
        'SELECT allowed_ip_id FROM allowed_ip WHERE ip_address = :ip AND allowed_ip_id <> CAST(:id AS bigint)',
        { ip: v.ipAddress, id: idText },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'ALLOWED_IP_DUPLICATED', '이미 등록된 IP입니다.');
      }
      await db.execute(
        'UPDATE allowed_ip SET ip_address = :ip, description = :description, use_yn = :useYn, updated_at = now() WHERE allowed_ip_id = CAST(:id AS bigint)',
        { ip: v.ipAddress, description: v.description, useYn: v.useYn, id: idText },
      );
      return { allowedIpId: Number(idText) };
    });
  }

  @Delete('/allowed-ips/:allowedIpId')
  async deleteAllowedIp(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const idText = req.params['allowedIpId'];
    if (!/^\d+$/.test(idText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '허용 IP ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const count = await db.execute('DELETE FROM allowed_ip WHERE allowed_ip_id = CAST(:id AS bigint)', { id: idText });
      if (count === 0) {
        throw new ApiError(404, 'ALLOWED_IP_NOT_FOUND', '허용 IP를 찾을 수 없습니다.');
      }
      return {};
    });
  }
}

response.page:
import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Tiles,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  TextInput,
  Select,
  Pairs,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;
const USE_OPTIONS: [string, string][] = [['사용', '사용'], ['미사용', '미사용']];

type Panel = { mode: 'create' } | { mode: 'edit'; row: Row } | { mode: 'delete'; row: Row } | null;

export default function FnSfr01705Page({ role, notify }: PageProps) {
  const [pageNo, setPageNo] = useState(0);
  const [panel, setPanel] = useState<Panel>(null);
  const [ipAddress, setIpAddress] = useState('');
  const [description, setDescription] = useState('');
  const [useYn, setUseYn] = useState('사용');

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/allowed-ips', role, undefined, { page: pageNo, size: SIZE }),
    [pageNo, role],
  );
  const rows = data ? data.items : [];
  const usedCount = rows.filter((r) => r['useYn'] === '사용').length;
  const unusedCount = rows.filter((r) => r['useYn'] === '미사용').length;

  function openCreate() {
    setIpAddress('');
    setDescription('');
    setUseYn('사용');
    setPanel({ mode: 'create' });
  }

  function openEdit(row: Row) {
    setIpAddress(String(row['ipAddress'] ?? ''));
    setDescription(row['description'] ? String(row['description']) : '');
    setUseYn(String(row['useYn'] ?? '사용'));
    setPanel({ mode: 'edit', row });
  }

  function checkInput() {
    if (!ipAddress.trim()) {
      throw new Error('허용 IP를 입력해 주세요.');
    }
    if (!useYn) {
      throw new Error('사용 여부를 선택해 주세요.');
    }
  }

  async function submitCreate() {
    checkInput();
    await call('POST', '/allowed-ips', role, { ipAddress: ipAddress.trim(), description, useYn });
    notify('허용 IP를 등록했습니다.');
    setPanel(null);
    reload();
  }

  async function submitEdit(row: Row) {
    checkInput();
    await call('PUT', '/allowed-ips/' + String(row['allowedIpId']), role, { ipAddress: ipAddress.trim(), description, useYn });
    notify('허용 IP를 수정했습니다.');
    setPanel(null);
    reload();
  }

  async function submitDelete(row: Row) {
    await call('DELETE', '/allowed-ips/' + String(row['allowedIpId']), role);
    notify('허용 IP를 삭제했습니다.');
    setPanel(null);
    reload();
  }

  const formFields = (
    <>
      <Field label="허용 IP" required>
        <TextInput value={ipAddress} onChange={setIpAddress} placeholder="예: 192.168.0.10" />
      </Field>
      <Field label="사용 여부" required>
        <Select value={useYn} onChange={setUseYn} options={USE_OPTIONS} />
      </Field>
      <Field label="설명" wide>
        <TextInput value={description} onChange={setDescription} multiline />
      </Field>
    </>
  );

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>등록 현황</h2>
        <Tiles
          items={[
            ['전체 허용 IP', <Num value={data ? data.total : 0} />],
            ['사용 (현재 쪽)', <Num value={usedCount} />],
            ['미사용 (현재 쪽)', <Num value={unusedCount} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>허용 IP 목록</h2>
        {error ? <ErrorText text={error} /> : null}
        <Band total={data ? data.total : 0}>
          <button type="button" onClick={openCreate}>허용 IP 등록</button>
        </Band>
        <DataTable
          rows={rows}
          empty="등록된 허용 IP가 없습니다."
          columns={[
            { key: 'ipAddress', label: '허용 IP' },
            { key: 'description', label: '설명' },
            { key: 'useYn', label: '사용 여부', render: (r: Row) => <Badge value={r['useYn']} /> },
            {
              key: 'actions',
              label: '처리',
              render: (r: Row) => (
                <span>
                  <button type="button" onClick={(e) => { e.stopPropagation(); openEdit(r); }}>수정</button>
                  <button type="button" onClick={(e) => { e.stopPropagation(); setPanel({ mode: 'delete', row: r }); }}>삭제</button>
                </span>
              ),
            },
          ]}
        />
        <Pager page={pageNo} size={SIZE} total={data ? data.total : 0} onPage={setPageNo} />
      </section>
      {panel && panel.mode === 'create' ? (
        <Drawer title="허용 IP 등록" onClose={() => setPanel(null)}>
          <Form submit="등록" onSubmit={submitCreate}>
            {formFields}
          </Form>
        </Drawer>
      ) : null}
      {panel && panel.mode === 'edit' ? (
        <Drawer title="허용 IP 수정" onClose={() => setPanel(null)}>
          <Form submit="저장" onSubmit={() => submitEdit(panel.row)}>
            {formFields}
          </Form>
        </Drawer>
      ) : null}
      {panel && panel.mode === 'delete' ? (
        <Drawer title="허용 IP 삭제" onClose={() => setPanel(null)}>
          <Form
            submit="삭제"
            danger
            note="삭제하면 되돌릴 수 없습니다."
            onSubmit={() => submitDelete(panel.row)}
          >
            <Pairs
              items={[
                ['허용 IP', String(panel.row['ipAddress'] ?? '')],
                ['설명', String(panel.row['description'] ?? '')],
                ['사용 여부', <Badge value={panel.row['useYn']} />],
              ]}
            />
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
